"""Credentials generated by oasis (v0.16.0 S2): one 0600 env file is the database account of the
compose service and of Odoo; odoo.conf stays password-free; nothing prints a password.

Synthetic fixtures only: the setup fixture of test_setup (fake uv, scratch git and machine file), the
lifecycle fixture of test_lifecycle (fake docker and environment Python) and a fake psycopg2 module
for the connection probe. No real database, container or Odoo runs.
"""
import oasis_test_env  # noqa: F401  first: XDG_CONFIG_HOME is scratch (tests/oasis_test_env.py)
import json
import os
from pathlib import Path
import pty
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
import unittest

import test_lifecycle as lifecycle
import test_setup

ROOT = lifecycle.STAGE
ACCOUNT = ROOT / 'tools' / 'db_account.py'
MARKER = 'credentials-must-not-print-this'
# A fake psycopg2: connect() records its keyword arguments in FAKE_PG_LOG, then fails with
# FAKE_PG_ERROR when it is set; FAKE_PG_MISSING makes the import fail.
FAKE_PSYCOPG2 = '''import json, os
if os.environ.get('FAKE_PG_MISSING'):
    raise ImportError('no psycopg2')
class OperationalError(Exception):
    pass
class Connection:
    def close(self):
        pass
def connect(**kwargs):
    with open(os.environ['FAKE_PG_LOG'], 'w') as stream:
        json.dump(kwargs, stream)
    if os.environ.get('FAKE_PG_ERROR'):
        raise OperationalError(os.environ['FAKE_PG_ERROR'])
    return Connection()
'''


def account_lines(path):
    """The ODOO_DB_USER and ODOO_DB_PASSWORD assignments of an env file, in order."""
    return [line for line in path.read_text().splitlines() if line.startswith('ODOO_DB_')]


@unittest.skipUnless(shutil.which('git'), 'git is required')
class GeneratedAccountTests(unittest.TestCase):
    setUp = test_setup.SetupTests.setUp
    git = test_setup.SetupTests.git
    odoo_source = test_setup.SetupTests.odoo_source
    module = test_setup.SetupTests.module
    setup_cmd = test_setup.SetupTests.setup_cmd
    tree = test_setup.SetupTests.tree
    existing_workspace = test_setup.SetupTests.existing_workspace

    def test_setup_generates_the_account_in_one_0600_file_and_never_prints_it(self):
        result = self.setup_cmd('--apply', '--community', str(self.source), '--no-enterprise')
        self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
        config = self.checkout / '.oasis/config'
        env_file, conf = config / '.env', config / 'odoo.conf'
        user, password = account_lines(env_file)
        self.assertEqual(user, 'ODOO_DB_USER=oasis_shop')
        self.assertRegex(password, r'\AODOO_DB_PASSWORD=[A-Za-z0-9_-]{32}\Z')
        self.assertEqual(env_file.stat().st_mode & 0o777, 0o600)
        self.assertNotIn(password.split('=', 1)[1], result.stdout + result.stderr)
        self.assertIn(f'create {env_file} (mode 0600): ODOO_DB_USER oasis_shop and a generated ODOO_DB_PASSWORD\n',
                      result.stdout)
        # odoo.conf stays path-free and password-free: Odoo gets the account of the env file.
        text = conf.read_text()
        self.assertTrue(text.endswith('db_user =\ndb_password =\n'), text)
        self.assertIn(f'; db_user and db_password stay empty: oasis passes ODOO_DB_USER and ODOO_DB_PASSWORD of '
                      f'{env_file} to Odoo as PGUSER and PGPASSWORD.\n', text)
        # Nothing to fill in by hand: no step asks for a password.
        self.assertNotIn('fill in', result.stdout)
        self.assertNotIn('password', result.stdout.split('next steps:')[1].lower())
        # Every new workspace gets its own password.
        other = self.scratch / 'other'
        shutil.copytree(self.checkout, other, symlinks=True,
                        ignore=shutil.ignore_patterns('.oasis', 'oasis-workspace.toml'))
        self.checkout = other
        again = self.setup_cmd('--apply')
        self.assertEqual((again.returncode, again.stderr), (0, ''), again.stdout)
        self.assertNotEqual(account_lines(other / '.oasis/config/.env')[1], password)

    def test_a_kept_odoo_conf_with_an_account_gives_the_new_env_file_its_values(self):
        project = self.existing_workspace()
        conf, env_file = project / 'config/odoo.conf', project / 'config/.env'
        for options, expected in (
                (f'db_user = legacy\ndb_password = {MARKER}\n', ['ODOO_DB_USER=legacy', f'ODOO_DB_PASSWORD={MARKER}']),
                (f'db_password = {MARKER} $x\n', ['ODOO_DB_USER=oasis_shop', f"ODOO_DB_PASSWORD='{MARKER} $x'"])):
            with self.subTest(options=options):
                env_file.unlink(missing_ok=True)
                conf.write_text(f'[options]\ndb_port = 6543\n{options}')
                result = self.setup_cmd('--apply')
                self.assertEqual((result.returncode, result.stderr), (0, ''), result.stdout)
                self.assertNotIn(MARKER, result.stdout)
                self.assertEqual(account_lines(env_file), expected)
                self.assertEqual(env_file.stat().st_mode & 0o777, 0o600)
                source = (f'ODOO_DB_USER from db_user of {conf}' if 'db_user' in options
                          else 'ODOO_DB_USER oasis_shop')
                self.assertIn(f'create {env_file} (mode 0600): {source} and ODOO_DB_PASSWORD from db_password of '
                              f'{conf}\n', result.stdout)
        # A value the env file cannot hold is refused before anything is written.
        env_file.unlink()
        conf.write_text("[options]\ndb_port = 6543\ndb_password = it's \"two\"\n")
        before = self.tree()
        result = self.setup_cmd('--apply')
        self.assertEqual((result.returncode, result.stdout), (2, ''))
        self.assertEqual(result.stderr, f'ERROR: Cannot copy db_password of {conf} to {env_file}: docker compose would '
                                        f'not read its value as written; write {env_file} yourself, then run oasis '
                                        'setup again.\n')
        self.assertEqual(self.tree(), before)


class LaunchTests(unittest.TestCase):
    """Every command that starts Odoo passes the env file's account through the environment."""
    setUp_fixture = lifecycle.LifecycleTests.setUp
    invoke = lifecycle.LifecycleTests.invoke

    def setUp(self):
        self.setUp_fixture()
        for name in ('PGUSER', 'PGPASSWORD'):
            self.env.pop(name, None)
        # The fake Odoo also records the account it was given, and whether argv holds the password.
        self.python.write_text(self.python.read_text().replace(
            'printf "odoo %s\\n" "$*" >> "$FAKE_LOG"\n',
            'printf "odoo %s\\n" "$*" >> "$FAKE_LOG"\n'
            'printf "account user=%s password=%s\\n" "${PGUSER-<unset>}" "${PGPASSWORD-<unset>}" >> "$FAKE_LOG"\n'))
        (self.root / 'dev/.env').write_text(f"ODOO_DB_USER=oasis_cc\nODOO_DB_PASSWORD='{MARKER} $x'\n")

    def accounts(self):
        lines = self.commands.read_text().splitlines()
        for line in lines:
            if line.startswith(('odoo ', 'docker ')):
                self.assertNotIn(MARKER, line)
        return [line for line in lines if line.startswith('account ')]

    def test_odoo_gets_the_env_file_account_through_the_environment(self):
        result = self.invoke('install-module', 'coffee')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (0, '', ''))
        self.assertEqual(self.accounts(), [f'account user=oasis_cc password={MARKER} $x'])
        self.env['FAKE_EXISTS'] = '1'
        self.commands.unlink()
        result = self.invoke('odoo-shell', 'cc_dev_coffee', input='print(1)\n')
        self.assertEqual((result.returncode, result.stderr), (0, ''))
        self.assertEqual(self.accounts(), [f'account user=oasis_cc password={MARKER} $x'])

    def test_what_odoo_conf_sets_is_kept_and_not_exported(self):
        conf = self.root / 'dev/odoo.conf'
        for options, expected in (('db_user = mine\ndb_password = theirs\n', 'user=<unset> password=<unset>'),
                                  ('db_user = mine\ndb_password =\n', f'user=<unset> password={MARKER} $x'),
                                  ('db_password = False\n', f'user=oasis_cc password={MARKER} $x')):
            with self.subTest(options=options):
                conf.write_text(lifecycle.conf_text(options))
                self.commands.unlink(missing_ok=True)
                result = self.invoke('install-module', 'coffee')
                self.assertEqual((result.returncode, result.stdout, result.stderr), (0, '', ''))
                self.assertEqual(self.accounts(), [f'account {expected}'])

    def test_exports_are_refused_on_a_terminal(self):
        master, slave = pty.openpty()
        self.addCleanup(os.close, master)
        try:
            result = subprocess.run([sys.executable, '-I', '-B', str(ACCOUNT), 'exports', str(self.root / 'dev/odoo.conf'),
                                     str(self.root / 'dev/.env')], stdout=slave, stderr=subprocess.PIPE, text=True)
        finally:
            os.close(slave)
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stderr, 'ERROR: db_account.py exports writes the account only to a pipe, never to '
                                        'a terminal.\n')


class ProbeTests(unittest.TestCase):
    """db_account.py probe: Odoo's account against the PostgreSQL odoo.conf names, one word out."""

    def setUp(self):
        self.scratch = Path(tempfile.mkdtemp(prefix='oasis-credentials-')).resolve()
        self.addCleanup(shutil.rmtree, self.scratch, ignore_errors=True)
        (self.scratch / 'fake/psycopg2').mkdir(parents=True)
        (self.scratch / 'fake/psycopg2/__init__.py').write_text(FAKE_PSYCOPG2)
        self.conf, self.env_file = self.scratch / 'odoo.conf', self.scratch / 'account'
        self.conf.write_text('[options]\ndb_host = 127.0.0.1\ndb_port = 6001\ndb_user =\ndb_password =\n')
        self.env_file.write_text(f'# account\nexport ODOO_DB_USER="oasis_cc"\nODOO_DB_PASSWORD={MARKER} # kept\n')
        self.log = self.scratch / 'connect.json'
        self.env = {key: value for key, value in os.environ.items() if not key.startswith(('PG', 'FAKE_'))}
        self.env.update(PYTHONPATH=str(self.scratch / 'fake'), FAKE_PG_LOG=str(self.log), PYTHONDONTWRITEBYTECODE='1')

    def probe(self, **env):
        result = subprocess.run([sys.executable, '-B', str(ACCOUNT), 'probe', str(self.conf), str(self.env_file)],
                                capture_output=True, text=True, env={**self.env, **env}, timeout=60)
        self.assertNotIn(MARKER, result.stdout + result.stderr)
        return result

    def test_it_connects_with_odoos_account(self):
        result = self.probe()
        self.assertEqual((result.returncode, result.stdout, result.stderr), (0, 'ready\n', ''))
        self.assertEqual(json.loads(self.log.read_text()), {
            'dbname': 'postgres', 'connect_timeout': 5, 'host': '127.0.0.1', 'port': '6001', 'user': 'oasis_cc',
            'password': MARKER})
        # What odoo.conf sets wins, as Odoo reads it; an empty db_host is left to libpq, like Odoo.
        self.conf.write_text('[options]\ndb_port = 6001\ndb_user = mine\ndb_password = theirs\n')
        self.assertEqual(self.probe().stdout, 'ready\n')
        self.assertEqual(json.loads(self.log.read_text()), {
            'dbname': 'postgres', 'connect_timeout': 5, 'port': '6001', 'user': 'mine', 'password': 'theirs'})

    def test_each_failure_is_one_word_without_the_server_message(self):
        for message, word in (('FATAL:  password authentication failed for user "oasis_cc"', 'authentication_failed'),
                              ('FATAL:  role "oasis_cc" does not exist', 'authentication_failed'),
                              ('fe_sendauth: no password supplied', 'authentication_failed'),
                              ('connection to server at "127.0.0.1", port 6001 failed: Connection refused',
                               'not_running'),
                              ('could not connect to server: No such file or directory', 'not_running'),
                              ('timeout expired', 'not_running'),
                              ('FATAL:  the database system is starting up', 'failed')):
            with self.subTest(message=message):
                result = self.probe(FAKE_PG_ERROR=message)
                self.assertEqual((result.returncode, result.stdout, result.stderr), (0, f'{word}\n', ''))
        result = self.probe(FAKE_PG_MISSING='1')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (0, 'no_driver\n', ''))


class CheckEnvironmentConnectionTests(unittest.TestCase):
    """check-environment --full connects with Odoo's account (tools/db_account.py probe), not psql."""
    setUp = lifecycle.LifecycleTests.setUp
    invoke = lifecycle.LifecycleTests.invoke

    def prepare(self):
        import test_environment
        test_environment.EnvironmentTests.prepare(self)
        test_environment.EnvironmentTests.running_database(self)
        (self.root / 'dev/compose.yml').write_text('name: cc-shop\nservices:\n  db:\n    image: postgres:17\n')

    def test_an_authentication_failure_names_the_volume_recreate(self):
        self.prepare()
        self.env['FAKE_CONNECTION'] = 'authentication_failed'
        result = self.invoke('check-environment', '--full')
        self.assertEqual(result.returncode, 1)
        self.assertIn('PASS postgres_service=running\n', result.stdout)
        command = shlex.join(['oasis', '--project', str(self.root), 'recreate-database-volume', '--confirm', 'cc-shop'])
        self.assertTrue(result.stderr.endswith(
            'FAIL postgres_connection=authentication_failed\n'
            f'  fix: the PostgreSQL that {self.root / "dev/odoo.conf"} names refuses the account Odoo uses: its volume '
            f'was initialized with other credentials than {self.root / "dev/.env"}; {command} recreates it with them '
            '(Tier B: it deletes every database of the service)\n'), result.stderr)
        self.assertNotIn('exec psql', self.commands.read_text())
        self.env['FAKE_CONNECTION'] = 'ready'
        result = self.invoke('check-environment', '--full')
        self.assertIn('PASS postgres_connection=ready\n', result.stdout)


class RecreateVolumeTests(unittest.TestCase):
    """recreate-database-volume is Tier B: --confirm <compose project>, else the plan and a refusal."""
    setUp_fixture = lifecycle.LifecycleTests.setUp

    def setUp(self):
        self.setUp_fixture()
        (self.root / 'dev/compose.yml').write_text("name: 'cc-shop'\nservices:\n  db:\n    image: postgres:17\n")
        (self.root / 'dev/.env').write_text(f'ODOO_DB_USER=oasis_cc\nODOO_DB_PASSWORD={MARKER}\n')

    def cli(self, *args):
        result = subprocess.run([sys.executable, '-B', str(ROOT / 'oasis'), '--project', str(self.root),
                                 'recreate-database-volume', *args], text=True, capture_output=True, cwd=self.root,
                                env=self.env)
        self.assertNotIn(MARKER, result.stdout + result.stderr)
        return result

    def calls(self):
        return self.commands.read_text().splitlines() if self.commands.exists() else []

    def plan(self):
        return (f'compose_project=cc-shop\ncompose_file={self.root / "dev/compose.yml"}\nservice=db\n'
                f'account={self.root / "dev/.env"}\n'
                'deletes=the volumes of compose project cc-shop: every database of its PostgreSQL, the trash '
                'included\n')

    def test_without_the_exact_compose_project_it_prints_the_plan_and_changes_nothing(self):
        command = shlex.join(['oasis', '--project', str(self.root), 'recreate-database-volume', '--confirm', 'cc-shop'])
        result = self.cli()
        self.assertEqual((result.returncode, result.stdout, result.stderr), (2, self.plan(), (
            'ERROR: recreate-database-volume deletes the PostgreSQL volume of compose project cc-shop and every '
            f'database in it, then starts the service again with the account of {self.root / "dev/.env"} (Tier B: it '
            f'needs explicit confirmation); nothing changed. Run: {command}\n')))
        result = self.cli('--confirm', 'other')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (2, self.plan(), (
            f'ERROR: --confirm other does not name the compose project cc-shop; nothing changed. Run: {command}\n')))
        self.assertEqual(self.calls(), [])

    def test_with_the_compose_project_it_removes_the_volume_and_starts_the_service(self):
        result = self.cli('--confirm=cc-shop')
        self.assertEqual((result.returncode, result.stderr), (0, ''))
        self.assertEqual(result.stdout, self.plan() + (
            f'Recreated the database volume of cc-shop; service db runs with the account of {self.root / "dev/.env"}.\n'))
        compose = f'docker compose --env-file {self.root / "dev/.env"} -f {self.root / "dev/compose.yml"}'
        self.assertEqual(self.calls(), [f'{compose} down -v', f'{compose} up -d --wait --wait-timeout 60 db'])

    def test_usage_errors_and_a_compose_file_without_a_name(self):
        # Like drop-database, the usage names the entry point that ran the tool.
        usage = f'Usage: {ROOT / "oasis"} [--confirm <compose project>]\n'
        for args in (('--confirm',), ('--confirm=',), ('--conf', 'cc-shop'), ('extra',),
                     ('--confirm', 'a', '--confirm', 'a')):
            with self.subTest(args=args):
                result = self.cli(*args)
                self.assertEqual((result.returncode, result.stdout, result.stderr), (2, '', usage))
        result = self.cli('--help')
        self.assertEqual((result.returncode, result.stderr), (0, ''))
        self.assertTrue(result.stdout.startswith(usage), result.stdout)
        (self.root / 'dev/compose.yml').write_text('services:\n  db:\n    image: postgres:17\n')
        result = self.cli('--confirm', 'cc-shop')
        self.assertEqual((result.returncode, result.stdout, result.stderr), (2, '', (
            f'ERROR: {self.root / "dev/compose.yml"} has no top-level name: add one (oasis doctor checks it), then run '
            'recreate-database-volume again.\n')))
        self.assertEqual(self.calls(), [])


